        if not _seeked:
            if session.get('resume'):
                target=resume_position(progress(session['pid'],session['kind'],session['sid'],session.get('series_id',''),session.get('season','')))
                if target:
                    if xbmc.getCondVisibility('Player.SeekEnabled'):
