        root=xml(read(Path(__file__).parents[1]/'bingie50/IncludesXCMate50.xml'))
        index=data.rfind(b'</includes>')
        return edit(data,[(index,index,b'\n'+b'\n'.join(ET.tostring(n,encoding='utf-8') for n in root)+b'\n')])
